import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;

public class SecureFileDownloadServlet {
    public void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String fileName = request.getParameter("file");
        File baseDir = new File("/var/www/public/").getCanonicalFile();
        File file = new File(baseDir, fileName).getCanonicalFile();

        // Ensure the resolved path starts with the base directory path
        if (!file.getPath().startsWith(baseDir.getPath() + File.separator)) {
            throw new SecurityException("Invalid file path");
        }

        FileInputStream fis = new FileInputStream(file);
        // ... copy stream to response output stream
    }
}
